x = abs(int(input()))
csc = []

for i in range(0, 45003):
    csc.append(i * (i + 1) // 2)

def solve(csc, x):
    for i in range(45000 + 1):
        if x == csc[i]:
            return i
        elif x < csc[i]:
            diff = csc[i] - x
            if diff % 2 == 0:
                return i
            diff1 = csc[i + 1] - x
            if diff1 % 2 == 0:
                return i + 1
            return i + 2

print(solve(csc, x))

"""
Jack is working on his jumping skills recently. Currently he's located at point zero of the number line. He would like to get to the point x. In order to train, he has decided that he'll first jump by only one unit, and each subsequent jump will be exactly one longer than the previous one. He can go either left or right with each jump. He wonders how many jumps he needs to reach x.

Input
The input data consists of only one integer x ( - 109 ≤ x ≤ 109).

Output
Output the minimal number of jumps that Jack requires to reach x.
"""
from math import *

def is_even(a):
    return False if a%2 else True

def calc_sum(n):
    return n * (n + 1)/2

def check(a, x):
    return (not is_even(a) and not is_even(x)) or (is_even(a) and is_even(x))

x = abs(int(input()))

if x == 0:
    print(0)
else:
    n = (-1+pow(1+4*2*x, 0.5))/2

    ceil_n = ceil(n)

    if check(calc_sum(ceil_n), x):
        print(ceil_n)
    else:
        if check(calc_sum(ceil_n + 1), x):
            print(ceil_n + 1)
        else:
            print(ceil_n + 2)

import math
from math import sqrt
x=int(input())
if x<0:
    x=-x
ans=int(0)
r=int((-1+sqrt(1+8*x))/2)+1
for i in range(max(0,r-6),r+6,1):
    if i*(i+1)/2>=x:
        ans=i
        break
if (ans*(ans+1)//2-x)%2==1:
    ans=ans+1
if (ans*(ans+1)//2-x)%2==1:
    ans=ans+1
print(ans)

class Solve:

    def __init__(self):
        self.x = 0;
        self.dem = 0;

    def vao(self):
        self.x = int(input());

    def lam(self):
        tong = 0;
        i = 1;
        while(tong + i<= abs(self.x)):
            tong += i;
            self.dem += 1;
            i += 1;
        while(tong < abs(self.x) or (tong - abs(self.x)) % 2 != 0):
            tong += i;
            self.dem += 1;
            i += 1;

    def ra(self):
        print(self.dem);


def main():
    p = Solve();
    p.vao();
    p.lam();
    p.ra();

main();

import queue

class Solve:

    def __init__(self) -> None:
        self.x = 0;
        self.dem = 0;

    def vao(self) -> None:
        self.x = abs(int(input()));

    def lam(self) -> None:
        tong = 0;
        # Vòng while lặp đến khi tìm được số có hiệu của số đó với x chia hết cho 2
        # Biến tổng được tính bằng cách cộng các chỉ số của mỗi bước nhảy tiến cho đến khi thỏa mãn điều kiện
        # Vậy khi thay 1 bước nhảy bất kỳ thành lùi thì tổng sẽ giảm đi một lượng là 2 * chỉ số của bước nhảy tương ứng
        while(tong < self.x or (tong - self.x) % 2 != 0):
            self.dem += 1;
            tong += self.dem;

    def ra(self) -> None:
        print(self.dem);


def main():
    p = Solve();
    p.vao();
    p.lam();
    p.ra();

main();

